import Foundation

/// Apple's certificate authorities (public certificates from apple.com/certificateauthority). A code signature has to carry the
/// whole chain from your certificate up to Apple's root; a `.p12` usually holds only your own certificate, and the address the
/// certificate names for its issuer isn't reliable (Apple's `certs.apple.com/wwdrg3.der` answers 404), so they're built in.
enum AppleCertificateAuthorities {
    static let all: [Data] = [
        Data(base64Encoded: "")!,   // Apple Root CA
        Data(base64Encoded: "")!,   // Apple Root CA - G2
        Data(base64Encoded: "")!,   // Apple Root CA - G3
        Data(base64Encoded: "")!,   // WWDR G2
        Data(base64Encoded: "")!,   // WWDR G3
        Data(base64Encoded: "")!,   // WWDR G4
        Data(base64Encoded: "")!,   // WWDR G5
        Data(base64Encoded: "")!,   // WWDR G6
    ]

    /// The issuing certificates above `chain`'s last certificate, found by matching issuer names, up to a root.
    static func completing(_ chain: [Data]) -> [Data] {
        var result = chain
        while let last = result.last, let fields = CertificateFields(der: last), !fields.isSelfIssued,
              let issuer = all.first(where: { CertificateFields(der: $0)?.subject == fields.issuer }), !result.contains(issuer) {
            result.append(issuer)
        }
        return result
    }
}
